#include <stdio.h>

static int accept(int value, int *out)
{
    if (value < 0) {
        return 0;
    }
    *out = value;
    return 1;
}

int main(void)
{
    int answer = 7;
    int ok = accept(-2, &answer);
    printf("%d %d\n", ok, answer);
    return 0;
}

